 1720	  public func selectBest(
 1721	    candidates: [CoreAgentHarnessCandidate],
 1722	    evaluations: [CoreAgentHarnessEvaluation]
 1723	  ) throws -> CoreAgentHarnessOptimizationResult {
 1724	    var seenCandidates: Set<String> = []
 1725	    for candidate in candidates {
 1726	      guard seenCandidates.insert(candidate.id).inserted else {
 1727	        throw CoreAgentSkillOptimizationError.duplicateHarnessCandidate(candidate.id)
 1728	      }
 1729	    }
 1730	    let candidateByID = Dictionary(uniqueKeysWithValues: candidates.map { ($0.id, $0) })
 1731	    var audit: [CoreAgentHarnessAuditEntry] = []
 1732	    for candidate in candidates {
 1733	      let scores = evaluations.filter { $0.candidateID == candidate.id }
 1734	      guard !scores.isEmpty else {
 1735	        throw CoreAgentSkillOptimizationError.missingHarnessEvaluation(candidate.id)
 1736	      }
 1737	      let meanScore = scores.map(\.score).reduce(0, +) / Double(scores.count)
 1738	      audit.append(
 1739	        CoreAgentHarnessAuditEntry(
 1740	          candidateID: candidate.id,
 1741	          meanScore: meanScore,
 1742	          heldoutSuiteIDs: Array(Set(scores.map(\.heldoutSuiteID))).sorted()
 1743	        )
 1744	      )
 1745	    }
 1746	    audit.sort { lhs, rhs in
 1747	      if lhs.meanScore != rhs.meanScore {
 1748	        return lhs.meanScore > rhs.meanScore
 1749	      }
 1750	      return lhs.candidateID < rhs.candidateID
 1751	    }
 1752	    guard let bestEntry = audit.first,
